// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {W_WALLET, Log} from "../src/W_WALLET.sol";

contract InvMutTest is Test {
    W_WALLET c;
    function setUp() public { c = new W_WALLET(address(new Log())); }
    function testFuzz_property(uint256 amount, address actor, uint256 unlockTime) public {
        vm.assume(actor != address(0));
        vm.assume(amount > 0 && amount <= 100 ether);
        vm.deal(actor, amount);
        vm.prank(actor);
        c.Put{value: amount}(unlockTime);
        (uint256 unlockBefore, uint256 bal) = c.Acc(actor);
        assertTrue(bal == amount && (unlockTime > block.timestamp ? unlockBefore == unlockTime : unlockBefore >= block.timestamp), "deposit must be credited to caller balance");
    }
}
